entries[3952] = { ["name"] = "Schwacher Rekombobulator", ["text"] = "Wirken in 12.5 sek.\nReagenzien:\nBronzeröhre , Surrendes bronzenes Dingsda (2), Mittleres Leder (2), Moosachat\nSchwacher Rekombobulator\nSchmuck\nBenötigt Ingenieurskunst\n(140)\n10 Aufladungen" }
