entries[3954] = { ["name"] = "Mondsichtgewehr", ["text"] = "Wirken in 25 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nBronzeröhre (3), Surrendes bronzenes Dingsda (3), Schwerer Griff , Geringer Mondstein (2)\nMondsichtgewehr\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n23 - 44 Schaden Tempo 1.70\n(19.71 Schaden pro Sekunde)\nHaltbarkeit 65 / 65\n24" }
entries[3955] = { ["name"] = "Explodierendes Schaf", ["text"] = "Wirken in 3 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nBronzegerüst , Surrendes bronzenes Dingsda , Schweres Sprengpulver (2), Wollstoff (2)\nBenötigt Ingenieurskunst\n(150)\nBenutzen: Beschwört ein explosives Schaf, das den nächsten Feind angreift, explodiert und dabei 135 to 165 Schaden verursacht. Hält 3 Minuten lang an oder bis zur Explosion. (1 Min Abklingzeit)" }
entries[3956] = { ["name"] = "Schutzbrille mit grünen Gläsern", ["text"] = "Wirken in 12.5 sek.\nTools: Bogenlichtschraubenschlüssel\nReagenzien:\nMittleres Leder (4), Moosachat (2), Fliegerbrille\nSchutzbrille mit grünen Gläsern\nWird beim Anlegen gebunden\nKopf Stoff\n66 Rüstung\n+8 Ausdauer\n+7 Willenskraft\nHaltbarkeit 70 / 70\nBenötigt Ingenieurskunst\n(150)" }
entries[3957] = { ["name"] = "Eisdeflektor", ["text"] = "Wirken in 12.5 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nSurrendes bronzenes Dingsda , Frostöl\n21\nBenutzen: Absorbiert 600 Frostschaden. Hält 1 Min. lang an. (15 Min Abklingzeit)\n5 Aufladungen" }
