entries[3959] = { ["name"] = "Diskombobulatorstrahl", ["text"] = "Wirken in 12.5 sek.\nTools: Schmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nSurrendes bronzenes Dingsda (3), Seidenstoff (2), Jade , Bronzeröhre\nBenutzen: Verwandelt das Ziel in einen Lepragnom und verringert 12 Sek. lang seinen Nahkampfschaden und seine Zaubermacht um 40 sowie sein Bewegungstempo um 20%. (1 Min Abklingzeit)\n5 Aufladungen" }
