entries[7156] = { ["name"] = "Wächterhandschuhe", ["text"] = "Wirken in 25 sek.\nReagenzien:\nSchweres Leder (4), Geschmeidiger schwerer Balg , Seidenfaden\nWächterhandschuhe\nWird beim Anlegen gebunden\nHände Leder\n95 Rüstung\n+12 Ausdauer\n+7 Intelligenz\nHaltbarkeit 40 / 40\n33" }
entries[7159] = { ["name"] = "Meucheln", ["text"] = "Nahkampfreichweite\nNächster Nahkampf\nFügt einem Gegner zusätzlichen Schaden zu, allerdings nur, wenn von hinten angegriffen wird." }
entries[7160] = { ["name"] = "Hinrichten", ["text"] = "Nahkampfreichweite\nNächster Nahkampf\nVersucht, einen verwundeten Feind ganz zu erledigen und verursacht dabei 120% normalen Waffenschaden. 'Hinrichten' kann nur bei Feinden angewendet werden, die über 20% oder weniger Gesundheit verfügen." }
entries[7162] = { ["name"] = "Erste Hilfe", ["text"] = "100 Meter Reichweite\nWirken in 3 sek.\nHeilt ein Ziel um den gleichen Wert wie den der maximalen Gesundheit des Zaubernden." }
entries[7164] = { ["name"] = "Verteidigungshaltung", ["text"] = "Sofort 3 min Abklingzeit\nNimmt eine Verteidigungshaltung ein. Hält 3 Min. lang an." }
entries[7165] = { ["name"] = "Kampfhaltung", ["text"] = "Sofort 3 min Abklingzeit\nNimmt eine ausbalancierte Gefechtshaltung ein, die Wut erzeugt, wenn der Krieger getroffen wird, und gleichzeitig Wutabfall verringert, wenn der Krieger sich nicht im Kampf befindet. Hält bis Abbruch lang an." }
entries[7178] = { ["name"] = "Wasseratmung", ["text"] = "Sofort 1 sek. Abklingzeit\nDer Anwender kann 30 Min. lang unter Wasser atmen." }
entries[7179] = { ["name"] = "Elixier der Wasseratmung", ["text"] = "Wirken in 3 sek.\nReagenzien:\nWürgetang , Schwarzmaulöl (2), Kristallphiole\n8\nBenutzen: Der Anwender kann 30 Min. lang unter Wasser atmen. (3 Sek. Abklingzeit)" }
entries[7181] = { ["name"] = "Großer Heiltrank", ["text"] = "Wirken in 3 sek.\nReagenzien:\nLebenswurz , Königsblut , Kristallphiole\n21\nBenutzen: Stellt 455 to 585 Gesundheit wieder her. (1 Min Abklingzeit)" }
entries[7183] = { ["name"] = "Elixier der schwachen Verteidigung", ["text"] = "Wirken in 3 sek.\nReagenzien:\nSilberblatt (2), Kristallphiole\nBenutzen: Erhöht Eure Rüstung 1 Stunde lang um 25 . Wächterelixier. (3 Sek. Abklingzeit)" }
entries[7184] = { ["name"] = "Kontrollverlust" }
entries[7211] = { ["name"] = "Teufelssaurierhaken", ["text"] = "5 Meter Reichweite\nSofort\nSticht einen Teufelssaurier und vergiftet ihn mit einer großen Dosis Gift." }
entries[7212] = { ["name"] = "Aufmerksam", ["text"] = "100 Meter Reichweite\nSofort\nErhöht Eure Verstohlenheitsentdeckung um 3." }
entries[7213] = { ["name"] = "Riesenmuschelrisotto", ["text"] = "Wirken in 2 sek.\nReagenzien:\nRiesenmuschelfleisch\n25\nBenutzen: Stellt im Verlauf von 27 Sek. 874.8 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 15 Min. lang 8 Ausdauer und Willenskraft." }
entries[7215] = { ["name"] = "Mithrilsporen" }
entries[7216] = { ["name"] = "Eisenschildstachel", ["text"] = "Wirken in 3 sek.\nBenötigt Schild\nBringt einen Eisenstachel an Eurem Schild an, der damit bei jedem Blocken Schaden verursacht." }
entries[7217] = { ["name"] = "Waffengegengewicht" }
entries[7218] = { ["name"] = "Waffengegengewicht", ["text"] = "Wirken in 3 sek.\nBringt ein Gegengewicht an einem Zweihandschwert, einem Zweihandstreitkolben, einer Zweihandaxt oder an einer Stangenwaffe an und erhöht die Tempowertung um 20." }
entries[7219] = { ["name"] = "Immun gegen Entwaffnen", ["text"] = "Immun gegen Entwaffnen." }
entries[7220] = { ["name"] = "Waffenkette", ["text"] = "Wirken in 3 sek.\nBenötigt Nahkampfwaffe\nBringt eine Kette an Eurer Waffe an, die die Wirkungsdauer von Entwaffnungseffekten um 60% verringert. Ist nicht mit ähnlichen Effekten stapelbar." }
entries[7221] = { ["name"] = "Eisenschildstachel", ["text"] = "Wirken in 12.5 sek.\nTools: Schmiedehammer\nReagenzien:\nEisenbarren (6), Grober Schleifstein (4)\nBenutzen: Bringt einen Eisenstachel an Eurem Schild an, der damit bei jedem Blocken Schaden verursacht." }
entries[7222] = { ["name"] = "Eisengegengewicht", ["text"] = "Wirken in 25 sek.\nTools: Schmiedehammer\nReagenzien:\nEisenbarren (4), Grober Schleifstein (2), Geringer Mondstein\nBenutzen: Bringt ein Gegengewicht an einem Zweihandschwert, einem Zweihandstreitkolben, einer Zweihandaxt oder an einer Stangenwaffe an und erhöht die Tempowertung um 20." }
entries[7223] = { ["name"] = "Goldene Schuppenarmschienen", ["text"] = "Wirken in 25 sek.\nTools: Schmiedehammer\nReagenzien:\nStahlbarren (5), Schwerer Schleifstein (2)\nGoldene Schuppenarmschienen\nWird beim Anlegen gebunden\nHandgelenke Kette\n106 Rüstung\n+4 Stärke\n+4 Ausdauer\nHaltbarkeit 40 / 40\n32\nAnlegen: Erhöht Eure Waffenkundewertung um 4." }
entries[7224] = { ["name"] = "Stahlwaffenkette", ["text"] = "Wirken in 25 sek.\nTools: Schmiedehammer\nReagenzien:\nStahlbarren (8), Schwerer Schleifstein (2), Schweres Leder (4)\nBenutzen: Bringt eine Kette an Eurer Waffe an, die die Wirkungsdauer von Entwaffnungseffekten um 60% verringert. Ist nicht mit ähnlichen Effekten stapelbar." }
