entries[7268] = { ["name"] = "Arkane Geschosse", ["text"] = "60 Meter Reichweite\nSofort\nSchleudert arkane Geschosse auf den Feind, die 2.25 Sek. lang alle 0.8 Sek. 372 Arkanschaden verursachen." }
entries[7272] = { ["name"] = "Staubwolke", ["text"] = "Sofort\nEine donnernde Staubwolke fliegt ins Gesicht der Gegner in der Nähe und verringert 5 Sek. lang ihre Trefferchance um 20%." }
entries[7273] = { ["name"] = "Blitzschlagbalg", ["text"] = "1 sek. Abklingzeit\nNatürliche Reservoirs im Panzer der Schildkröte speichern solare Energie und verursachen Naturschaden bei Nahkampfangreifern." }
entries[7276] = { ["name"] = "Gift Proc", ["text"] = "(Procchance: 5%)" }
entries[7277] = { ["name"] = "Abbau-Schwarm" }
entries[7278] = { ["name"] = "Sammlerschwarm beschwören", ["text"] = "Sofort\nBeschwört 1 Sammlerschwarm, um dem Zaubernden 2 Min. lang im Kampf zu helfen." }
entries[7279] = { ["name"] = "Schwarzer Schlick", ["text"] = "Nahkampfreichweite\nWirken in 3 sek.\nErhöht die Zeit zwischen Angriffen in der Nähe befindlicher Feinde um 25% und verlangsamt ihr Bewegungstempo um 30%. Hält 10 Sek. lang an." }
entries[7285] = { ["name"] = "Horn der Maraudine blasen", ["text"] = "5 Meter Reichweite\nSofort\nDas Kriegshorn der Maraudine platzieren und blasen." }
entries[7289] = { ["name"] = "Schrumpfen", ["text"] = "30 Meter Reichweite\nWirken in 3 sek.\nVerringert 20 Sek. lang die Stärke und Ausdauer eines Gegners." }
entries[7290] = { ["name"] = "Seelenentzug", ["text"] = "10 Mana 10 Meter Reichweite\nKanalisiert (Wirken in 10 sek.) 1 sek. Abklingzeit\nEntzieht einem Feind und seinem nächsten Verbündeten 10 Sek. lang Gesundheit und heilt den Zaubernden um bis zu 200% des entzogenen Betrags." }
entries[7293] = { ["name"] = "Zombiegestalt" }
entries[7294] = { ["name"] = "Aura der Vergeltung", ["text"] = "Sofort\nVerursacht bei jedem Feind, der ein Gruppen- oder Schlachtzugsmitglied schlägt, das sich im Umkreis von 40 Metern befindet, 116 Heiligschaden. Spieler können pro Paladin nur jeweils eine Aura besitzen." }
entries[7295] = { ["name"] = "Seelensauger", ["text"] = "40 Meter Reichweite\nWirken in 2 sek.\nMacht einen Feind 5 Sek. lang bewegungsunfähig, entzieht 35 Gesundheit und überträgt sie auf den Zaubernden." }
entries[7302] = { ["name"] = "Frostrüstung", ["text"] = "Sofort\nVerringert den erlittenen körperlichen Schaden um 15% [ Glyphe 'Frostrüstung' : und regeneriert alle 5 Sek. 0% seines maximalen Manas ]. Wenn ein Feind den Zaubernden schlägt, kann 5 Sek. lang sein Bewegungstempo um 30% verlangsamt und die Zeit zwischen seinen Angriffen um 20% erhöht werden. Es kann immer nur ein Rüstungszauber zur selben Zeit auf dem Magier aktiv sein. Hält 30 Min. lang an." }
entries[7321] = { ["name"] = "Kälte", ["text"] = "30 Meter Reichweite\nSofort\nVerringert das Bewegungstempo des Angreifers um 30% und erhöht die Zeit zwischen seinen Angriffen um 20%." }
entries[7328] = { ["name"] = "Erlösung", ["text"] = "64% von Grundmana 40 Meter Reichweite\nWirken in 10 sek.\nBringt einen Spieler mit 35% des Maximalwertes von Gesundheit und Mana ins Leben zurück. Kann nicht während des Kampfes verwendet werden." }
