entries[7344] = { ["name"] = "Rekombobulieren" }
entries[7353] = { ["name"] = "Gemütliches Feuer", ["text"] = "Sofort\nErhöht Eure Willenskraft um 4." }
entries[7355] = { ["name"] = "Feststecken", ["text"] = "Wirken in 10 sek." }
entries[7356] = { ["name"] = "Wache rufen" }
entries[7357] = { ["name"] = "Giftiger Stich", ["text"] = "Nahkampfreichweite\nSofort\nVerursacht alle 3 Sek. Naturschaden bei einem Feind, erhöht die Zeit zwischen seinen Angriffen um 10% und verringert 10 Sek. lang sein Bewegungstempo." }
entries[7358] = { ["name"] = "Gemütliches Feuer", ["text"] = "Sofort\nErhöht Eure Willenskraft um 8." }
entries[7363] = { ["name"] = "Feuerleuchten", ["text"] = "Sofort 1 sek. Abklingzeit\nErhöht die Willenskraft der in der Nähe befindlichen Gruppenmitglieder um 4." }
entries[7364] = { ["name"] = "Lichtfackel" }
entries[7365] = { ["name"] = "Flasche Gift", ["text"] = "15 Meter Reichweite\nWirken in 2 sek.\nWirft eine Flasche voll Gift auf den Feind und fügt ihm so 15 Sek. lang alle 3 Sek. Naturschaden zu." }
entries[7366] = { ["name"] = "Berserkerhaltung", ["text"] = "Sofort\nNimmt eine offensive Haltung ein, die Wut erzeugt, wenn der Krieger einen Gegner schlägt. Hält 4 Min. lang an." }
entries[7367] = { ["name"] = "Infizierter Biss", ["text"] = "Nahkampfreichweite\nSofort\nVerursacht alle 3 Sek. Naturschaden bei einem Feind und erhöht 15 Sek. lang seinen erlittenen körperlichen Schaden." }
entries[7370] = { ["name"] = "Sturmangriff" }
entries[7376] = { ["name"] = "Verteidigungshaltung - Passiv", ["text"] = "Verringert den erlittenen Schaden um 10%.\nErhöht die erzeugte Bedrohung um 10%." }
entries[7377] = { ["name"] = "Periodischen Immunschaden nehmen" }
entries[7381] = { ["name"] = "Berserkerhaltung - Passiv", ["text"] = "Eine offensive Haltung. Erhöht den verursachten Schaden um 10%." }
entries[7383] = { ["name"] = "Wasserblase" }
entries[7384] = { ["name"] = "Überwältigen", ["text"] = "5 Wut Nahkampfreichweite\nSpontanzauber\nBenötigt Nahkampfwaffe\nBenötigt Kampfhaltung\nSofortige Überwältigung des Feindes, die 126% Waffenschaden verursacht. Kann nur verwendet werden, nachdem das Ziel ausgewichen ist. Auf 'Überwältigen' kann nicht mit Blocken, Ausweichen oder Parieren reagiert werden." }
entries[7386] = { ["name"] = "Rüstung zerreißen", ["text"] = "15 Wut Nahkampfreichweite\nSpontanzauber\nBenötigt Nahkampfwaffe\nZerreißt die Rüstung Eures Ziels [ Glyphe 'Rüstung zerreißen' : sowie eines zweiten nahen Ziels ], wodurch der Rüstungswert um 4% verringert wird. Diese Fähigkeit verursacht ein hohes Maß an Bedrohung, die durch Angriffskraft noch erhöht wird. Bis zu 3-mal stapelbar. Hält 30 Sek. lang an." }
entries[7389] = { ["name"] = "Angreifen", ["text"] = "100 Meter Reichweite\nWirken in 2 sek.\nErhöht 15 Sek. lang das Angriffstempo des Tiers des Zaubernden um 50%." }
entries[7393] = { ["name"] = "Bruder heilen", ["text"] = "60 Meter Reichweite\nSofort\nHeilt das Ziel um 30000." }
entries[7394] = { ["name"] = "Drehender Streich", ["text"] = "Nahkampfreichweite\nNächster Nahkampf\nVerursacht normalen Schaden plus 5 bei in der Nähe befindlichen Feinden." }
entries[7395] = { ["name"] = "Todesminendynamit", ["text"] = "30 Meter Reichweite\nWirken in 2 sek.\nFügt allen Gegnern in einem ausgewählten Bereich Feuerschaden zu." }
entries[7396] = { ["name"] = "Lebertran", ["text"] = "Sofort\nErhöht Eure Nahkampftempowertung 30 Sek. lang um 100." }
entries[7398] = { ["name"] = "Geburt" }
entries[7399] = { ["name"] = "Erschrecken", ["text"] = "Nahkampfreichweite\nSofort\nErschreckt einen Feind und lässt ihn 3 Sek. lang voller Furcht flüchten. Es kann immer nur jeweils ein einzelnes Ziel mit Schrecken erfüllt werden." }
entries[7408] = { ["name"] = "Schwerer Kupferschlägel", ["text"] = "Wirken in 3 sek.\nTools: Schmiedehammer\nReagenzien:\nKupferbarren (12), Schwacher Fluxus (2), Leichtes Leder (2)\nSchwerer Kupferschlägel\nWird beim Anlegen gebunden\nZweihändig Streitkolben\n24 - 36 Schaden Tempo 2.80\n(10.71 Schaden pro Sekunde)\n+2 Stärke\n+2 Beweglichkeit\n+2 Ausdauer\nHaltbarkeit 55 / 55\n11" }
entries[7411] = { ["name"] = "Verzauberkunst", ["text"] = "Sofort\nErmöglicht einem Verzauberer, Standard-Gegenstände mit einer maximalen potenziellen Fertigkeit von 75 zu verzaubern. Es werden Staub und Essenzen benötigt, die durch Entzaubern von magischen Gegenständen gefunden wurden." }
entries[7412] = { ["name"] = "Verzauberkunst", ["text"] = "Sofort\nErmöglicht einem Verzauberer das Verzaubern von Waffen und Rüstung mit einer maximalen potenziellen Fertigkeit von 150." }
entries[7413] = { ["name"] = "Verzauberkunst", ["text"] = "Sofort\nErmöglicht einem Verzauberer das meisterhafte Verzaubern von Waffen und Rüstung mit einer maximalen potenziellen Fertigkeit von 225." }
