entries[7428] = { ["name"] = "Armschiene - Schwaches Ausweichen", ["text"] = "Wirken in 5 sek.\nBenötigt Armschienen\nTools: Runenverzierte Kupferrute\nReagenzien:\nGeringe Magieessenz , Seltsamer Staub\nArmschienen dauerhaft verzaubern, sodass die Ausweichwertung um 2 erhöht wird." }
